"""Form 5 Human Biology, modules 1 and 2 (human organization and cellular biology; support, movement
and the musculoskeletal system). One lesson per topic, 11 lessons."""

from .dsl import *  # noqa: F403

COURSE = ("human-biology", "form-5")

M1 = "Human Organization & Cellular Biology"
M2 = "Support, Movement & the Musculoskeletal System"

LESSONS = [
    lesson(
        module=M1, topic="Humans and other primates",
        title="Humans and other primates: what sets us apart",
        slug="hbi1-humans-and-primates", minutes=18,
        summary="Humans belong to the primates, the group that includes monkeys and apes, but several features of the skeleton, brain, hands and teeth set humans apart from the other primates.",
        objectives=["Place humans in the primate group and name some other primates",
                    "State the features that humans share with other primates",
                    "Describe the features that distinguish humans from apes and monkeys",
                    "Explain how upright walking and a large brain are linked to human features"],
        key_concepts=["Primate", "Bipedal", "Opposable thumb", "Cranial capacity", "Binocular vision"],
        blocks=[
            H("Introduction"),
            T("Look at a drill or a chimpanzee in a forest of southern Cameroon, then look at the person watching it. Both have forward-facing eyes, hands with fingers and a face with expressions. This is no accident: humans and chimpanzees are close relatives. Both belong to one group of mammals called the **primates**."),
            T("In this lesson you learn what humans share with other primates, and the features that make *Homo sapiens* (the scientific name of modern humans) different."),
            D("**Primates** are mammals with grasping hands and feet, forward-facing eyes, a large brain for their body size and (usually) one baby at a time. The group includes lemurs, monkeys, apes and humans.", title="Definition"),
            H("Features shared by primates"),
            T("All primates are mammals, so they have hair, mammary glands and a diaphragm. In addition, primates share features that suit life in trees, the home of most primates."),
            KEY("Primate features", "These are common to humans, monkeys and apes.", cards=[
                ["Grasping hands", "Five digits on each hand with nails (not claws) and a thumb that can move against the fingers, so the hand can grip branches and objects."],
                ["Forward-facing eyes", "Both eyes look forward and their fields of view overlap. This gives binocular vision: good judgement of distance, needed to jump between branches."],
                ["Large brain", "A large brain for the body size, with good memory, learning and coordination."],
                ["Few young, long care", "Usually one baby at a time, with a long period of parental care and learning."],
            ]),
            H("Features that distinguish humans"),
            T("Humans are closely related to the great apes (gorillas, chimpanzees and orang-utans), but they differ from them in the following ways. The most important change is that humans walk upright on two legs. Walking on two legs is called **bipedalism**."),
            D("A **bipedal** animal walks on two legs. The human skeleton is adapted for upright walking: the body weight passes down through the legs.", title="Definition"),
            CODE("""Feature              Human                     Ape (e.g. chimpanzee)
Walking              Upright, two legs         Mainly on all fours, knuckle-walking
Backbone             S-shaped curve            C-shaped curve
Pelvis               Short, wide, bowl-shaped  Long and narrow
Foot                 Arched, big toe in line   Flat, big toe can grip
Brain size           Large (about 1 400 cm3)   Smaller (about 400 cm3)
Face and jaws        Flat face, small jaws,    Sloping face, large jaws,
                     chin present              no chin
Canine teeth         Small, same level as      Large, project past
                     other teeth               other teeth
Arms and legs        Legs longer than arms     Arms longer than legs
Body hair            Little                    Thick""", "text", title="Humans compared with apes", caption="Brain sizes are approximate averages; textbooks give slightly different figures."),
            T("Each difference has a reason. The S-shaped backbone acts like a spring and keeps the head balanced above the hips. The wide pelvis supports the organs and gives the muscles of the buttocks something to hold. The arched foot absorbs shock and pushes the body forward. Because the hands are free from walking, humans use them for making and using tools. The thumb is long and fully **opposable**, which means it can touch the tip of each finger. This gives the precise grip used in writing, sewing or picking a cocoa pod."),
            IMG("f5hbi1-skeleton.svg", alt="Labelled front view of the human skeleton", caption="Figure 1. The human skeleton is adapted for upright walking: the pelvis and leg bones carry the body weight (diagram is schematic)."),
            H("Worked examples"),
            EX("Worked example 1: linking features to function", intro="Explain why the human big toe is in line with the other toes while a chimpanzee big toe sticks out to the side.", steps=[
                S("Say what the human foot does", text="A human foot is used for standing and walking on the ground, not for climbing."),
                S("Link the toe to the job", text="A big toe in line with the others, in an arched foot, pushes the body forward and carries weight."),
                S("Say what the ape foot does", text="A chimpanzee spends time in trees. Its big toe sticks out like a thumb and can grip branches."),
                S("State the conclusion", text="The human foot is adapted for bipedal walking; the ape foot is adapted for grasping."),
            ]),
            EX("Worked example 2: choose the difference", intro="A student says humans differ from chimpanzees because humans have hair and chimpanzees do not. Is she right?", steps=[
                S("Check the facts", text="Chimpanzees have thick hair; humans have thin body hair. Both are mammals and both have hair."),
                S("Decide", text="The student has the difference the wrong way round."),
                S("Give a correct difference", text="Humans have a larger brain, a flatter face with a chin, smaller canine teeth and walk upright."),
            ]),
            QUIZ("Which feature is found in humans but NOT in other primates?", [
                "Opposable thumb", "Binocular vision", "Fully upright, bipedal walking", "Nails instead of claws"], 2,
                 "Humans are the only primates that normally walk upright on two legs. Other primates share opposable thumbs, forward-facing eyes and nails.",
                 hint="Which feature do monkeys and apes share with us?",
                 feedback=["Monkeys and apes also have an opposable thumb.", "Binocular vision is a feature of all primates.", "", "Nails are a primate feature, shared with monkeys and apes."]),
            MISTAKE("Saying that humans come from chimpanzees", "Humans and chimpanzees share a common ancestor that lived long ago. Humans did not come from living chimpanzees. Write 'share a common ancestor' if the question asks about relationship."),
            MISTAKE("Calling every difference a 'better' feature", "Features are adaptations to different ways of life. A chimpanzee's long arms are not worse than our legs; they suit climbing."),
            QUIZ("Large canine teeth that project past the other teeth are found in", [
                "humans only", "apes and monkeys", "no primate", "all mammals equally"], 1,
                 "Apes and monkeys have large canines; humans have small canines at the same level as the other teeth.",
                 hint="Which group has a sloping face and large jaws?",
                 feedback=["Humans have small canine teeth.", "", "Many primates have them.", "Not all mammals have large canines; sheep, for example, have none like this."]),
            TIP("In Paper 1, this topic is often tested as 'which feature is found only in humans?' or 'which feature is adapted for bipedalism?'. Memorise the table above in pairs: human feature, then ape feature. In Paper 2 essays, describe a feature and say what it is for (the adaptation)."),
            PQ("Name three features shared by all primates.", "Grasping hands with nails, forward-facing eyes with binocular vision, a large brain for the body size. (Also accepted: one baby at a time with long parental care.)"),
            PQ("State four differences between the skull and teeth of a human and those of a chimpanzee.", "Human: larger brain case, flat face, small jaws, chin present, small canines. Chimpanzee: smaller brain case, sloping face, large jaws, no chin, large projecting canines. Any four differences."),
            PQ("Explain how the human pelvis and backbone are adapted for walking upright.", "The S-shaped backbone balances the head above the hips and absorbs shock. The pelvis is short, wide and bowl-shaped, so it supports the organs and carries the body weight onto the legs. The attached large muscles hold the body upright."),
            PQ("Why is an opposable thumb useful to humans?", "The thumb can touch each finger tip, giving a precise grip. Humans can hold tools, write and handle small objects, because the hands are free from walking."),
            SUM("Humans are primates, with monkeys, apes and lemurs.",
                "Primates share grasping hands with nails, forward-facing eyes (binocular vision) and a large brain.",
                "Humans are bipedal: S-shaped backbone, wide pelvis, arched foot and longer legs than arms.",
                "Humans have a larger brain, flat face with chin, small jaws and small canines.",
                "Humans share a common ancestor with apes; they did not come from living apes."),
        ],
    ),
    lesson(
        module=M1, topic="Cell ultrastructure",
        title="Cell ultrastructure: organelles and their jobs",
        slug="hbi1-cell-ultrastructure", minutes=22,
        summary="The animal cell contains organelles, each with a job: the nucleus controls the cell, mitochondria release energy, ribosomes make protein and the membrane controls what enters and leaves; plant cells add a wall, chloroplasts and a large vacuole.",
        objectives=["Name and locate the main organelles in an animal cell",
                    "State the function of each organelle",
                    "Compare plant and animal cells",
                    "Calculate magnification and actual size from a drawing"],
        key_concepts=["Organelle", "Nucleus", "Mitochondrion", "Ribosome", "Cell membrane", "Magnification"],
        blocks=[
            H("Introduction"),
            T("Think of a busy market in Douala. It has a manager's office, stalls that make and sell goods, power supply, a gate with guards and roads inside. A cell is organised in the same way. All the work of life takes place inside cells, and each small part of a cell has its own job."),
            T("Ultrastructure means the fine structure seen with an electron microscope, which magnifies far more than a light microscope. The small working parts inside a cell are called organelles."),
            D("An **organelle** is a small structure inside a cell that has a particular job. The organelles lie in the **cytoplasm**, the jelly-like material of the cell where chemical reactions take place.", title="Definition"),
            IMG("f5hbi1-animal-cell.svg", alt="Labelled animal cell showing membrane, nucleus, mitochondria, ribosomes, Golgi body, cytoplasm and rough ER", caption="Figure 1. An animal cell seen with an electron microscope (schematic; organelles are not to scale)."),
            H("Organelles and their functions"),
            KEY("The main organelles", "Learn each name with its job.", cards=[
                ["Cell membrane", "A thin layer around the cell. It controls which substances enter and leave (partially permeable)."],
                ["Nucleus", "Contains the chromosomes (DNA). It controls the activities of the cell and holds the instructions for making proteins."],
                ["Cytoplasm", "Jelly-like fluid where many chemical reactions of the cell happen."],
                ["Mitochondria", "Site of aerobic respiration. They release energy from glucose. Cells that use a lot of energy, such as muscle cells, have many."],
                ["Ribosomes", "Tiny structures where proteins are made. Some lie on the rough ER."],
                ["Endoplasmic reticulum (ER)", "A network of membranes. Rough ER has ribosomes and carries protein; smooth ER makes lipids."],
                ["Golgi body", "Stacks of flattened sacs that modify, package and send out substances such as enzymes."],
                ["Lysosomes", "Small sacs of digestive enzymes that break down worn-out parts and germs."],
            ]),
            H("Plant cells and animal cells"),
            T("Plant cells have all the organelles above, except that they usually have no centrioles, and they have three extra features."),
            CODE("""Feature              Animal cell          Plant cell
Cell wall            Absent               Present (cellulose)
Chloroplasts         Absent               Present in green parts
Large vacuole        Small or none        Large, central, sap
Shape                Round / irregular    Fixed, regular
Stored food          Glycogen             Starch""", "text", title="Plant and animal cells compared"),
            T("The cellulose wall gives support and shape. Chloroplasts contain chlorophyll for photosynthesis. The large vacuole contains cell sap and keeps the cell firm. In humans, red blood cells lose their nucleus when mature, and this gives more space for haemoglobin that carries oxygen."),
            H("Magnification"),
            T("Drawings of cells are always bigger than real cells. The magnification tells how many times bigger the image is than the real object."),
            F(r"\text{magnification} = \frac{\text{size of image}}{\text{actual size}}", title="Magnification formula"),
            T("Always put the image and actual size in the same units. 1 mm = 1 000 micrometres (µm)."),
            EX("Worked example 1: find the actual size", intro="A drawing of a cheek cell is 60 mm wide. The drawing magnification is ×1 200. Find the actual width of the cell in micrometres.", steps=[
                S("Rearrange the formula", math=r"\text{actual size} = \frac{\text{image size}}{\text{magnification}}"),
                S("Substitute", math=r"= \frac{60}{1200} = 0.05\ \text{mm}"),
                S("Change to micrometres", math=r"0.05 \times 1000 = 50\ \mu\text{m}"),
            ], check=r"50\ \mu\text{m} \times 1200 = 60\,000\ \mu\text{m} = 60\ \text{mm}"),
            EX("Worked example 2: find the magnification", intro="A red blood cell has an actual diameter of about 7 µm. In a photograph it measures 28 mm. What is the magnification?", steps=[
                S("Convert to the same unit", math=r"28\ \text{mm} = 28\,000\ \mu\text{m}"),
                S("Use the formula", math=r"\text{magnification} = \frac{28\,000}{7} = 4000"),
                S("State the answer", text="The magnification is ×4 000."),
            ]),
            MISTAKE("Mixing units in a magnification sum", "Convert both measurements to one unit before dividing. Dividing 60 mm by 1 200 gives an answer in mm; to give micrometres you must multiply by 1 000."),
            MISTAKE("Saying mitochondria 'make energy'", "Energy cannot be made. Write that mitochondria release energy from glucose during respiration."),
            QUIZ("Which organelle is the site of protein synthesis?", ["Nucleus", "Ribosome", "Mitochondrion", "Lysosome"], 1,
                 "Proteins are made at ribosomes. The nucleus holds the instructions but does not make the protein.",
                 hint="Think of tiny dots on the rough endoplasmic reticulum.",
                 feedback=["The nucleus carries the code (DNA) but proteins are assembled at ribosomes.", "", "Mitochondria release energy.", "Lysosomes digest unwanted materials."]),
            QUIZ("A cell from a root has no chloroplasts. Which structure would it still have, if it is a plant cell?", ["Cell wall", "Centrioles", "Glycogen granules", "Lysosomes only"], 0,
                 "Every plant cell has a cellulose cell wall, even without chloroplasts.",
                 hint="Which structure do plant cells have and animal cells lack, apart from chloroplasts?",
                 feedback=["", "Centrioles are mainly in animal cells.", "Plants store starch, not glycogen.", "Lysosomes do not define plant cells; the cell wall does."]),
            TIP("Paper 1 usually asks you to match an organelle to its function, or to identify an organelle from a labelled diagram. Paper 2 may ask you to draw and label a cell and to compare plant and animal cells in a table form. Draw with a sharp pencil and label with straight lines that do not cross."),
            PQ("State the function of (a) the nucleus, (b) mitochondria, (c) the cell membrane.", "(a) Controls the cell's activities and holds the chromosomes (DNA). (b) Release energy from glucose by respiration. (c) Controls the movement of substances into and out of the cell."),
            PQ("State two differences between a plant cell and an animal cell.", "A plant cell has a cellulose cell wall, chloroplasts and a large central vacuole; an animal cell has none of these (or a small vacuole). Any two."),
            PQ("A muscle cell has many more mitochondria than a skin cell. Explain.", "Muscle cells contract and use a lot of energy. Mitochondria release this energy by respiration, so more mitochondria supply the extra energy."),
            PQ("A cell is 40 µm long. Find its length on a drawing at magnification ×500, in mm.", "Image size = 40 × 500 = 20 000 µm = 20 mm."),
            SUM("Organelles are small structures inside the cell, each with a job.",
                "Nucleus controls the cell; mitochondria release energy; ribosomes make protein; membrane controls entry and exit.",
                "Rough ER carries proteins, the Golgi body packages them and lysosomes digest.",
                "Plant cells also have a cellulose wall, chloroplasts and a large vacuole.",
                "Magnification = image size ÷ actual size, using the same units."),
        ],
    ),
    lesson(
        module=M1, topic="Cell division",
        title="Cell division: mitosis and meiosis",
        slug="hbi1-cell-division", minutes=22,
        summary="Mitosis makes two identical diploid cells for growth and repair; meiosis makes four different haploid gametes with half the chromosomes, so that fertilisation restores the full number.",
        objectives=["State why cells divide and where mitosis and meiosis occur in humans",
                    "Describe the stages of mitosis in order",
                    "Describe how meiosis differs from mitosis",
                    "Use the numbers 46 and 23 to work out chromosome numbers"],
        key_concepts=["Chromosome", "Mitosis", "Meiosis", "Diploid", "Haploid", "Gamete"],
        blocks=[
            H("Introduction"),
            T("A baby born in Bamenda weighs about three kilograms. Twenty years later the same person is much larger, yet they started as one single cell. Cells make more cells by **dividing**. Cell division also repairs a cut on your hand and makes the sperm and egg cells needed for new life."),
            T("There are two kinds of cell division in humans. **Mitosis** is used for growth and repair. **Meiosis** is used only to make gametes (sex cells)."),
            H("Chromosomes"),
            D("A **chromosome** is a thread-like structure in the nucleus, made of DNA and protein, that carries genes. Human body cells have **46 chromosomes**, in 23 pairs.", title="Definition"),
            D("A cell with two sets of chromosomes (pairs) is **diploid** (2n). A cell with a single set is **haploid** (n). Human body cells are diploid, with 2n = 46. Human gametes are haploid, with n = 23.", title="Definition"),
            H("Mitosis"),
            T("In mitosis one cell divides to form two daughter cells. The daughter cells are genetically identical to the parent cell and have the same chromosome number (46). Before mitosis starts, in a resting phase called interphase, the cell copies its DNA, so that each chromosome consists of two identical **chromatids** joined at a point called the centromere."),
            KEY("Stages of mitosis", "The stages follow the order PMAT: prophase, metaphase, anaphase, telophase.", cards=[
                ["Prophase", "Chromosomes become short and thick and are visible as two chromatids. The nuclear membrane breaks down."],
                ["Metaphase", "Chromosomes line up along the middle (equator) of the cell, attached to spindle fibres."],
                ["Anaphase", "Spindle fibres shorten and pull the chromatids apart, to opposite ends of the cell."],
                ["Telophase", "Chromatids (now chromosomes) reach the poles, new nuclear membranes form, and the cytoplasm divides in two (cytokinesis)."],
            ]),
            T("Mitosis happens in the skin, in the bone marrow, in the lining of the gut and wherever the body grows or repairs itself. When you scrape your knee, mitosis replaces lost skin cells."),
            H("Meiosis"),
            T("Meiosis happens only in the testes (to make sperm) and ovaries (to make eggs). One diploid cell divides **twice** to make **four** haploid cells, each with 23 chromosomes. During the first division the pairs of chromosomes separate. During the second division the chromatids separate. The four cells are not identical to each other or to the parent, because of mixing of genes. This is the reason that brothers and sisters of the same parents look different."),
            T("At fertilisation a haploid sperm (23) joins a haploid egg (23) to form a diploid zygote (46). If gametes were made by mitosis, the number of chromosomes would double with every generation."),
            CODE("""Feature               Mitosis                  Meiosis
Where in humans       Most body tissues        Testes and ovaries
Purpose               Growth, repair           Making gametes
Divisions             One                      Two
Cells produced        2                        4
Chromosome number     Stays 46 (diploid)       Halved to 23 (haploid)
Daughter cells        Identical to parent      Different from parent""", "text", title="Mitosis compared with meiosis"),
            H("Worked examples"),
            EX("Worked example 1: chromosome numbers", intro="A human skin cell has 46 chromosomes. How many chromosomes are in (a) a daughter cell after mitosis, (b) a sperm cell?", steps=[
                S("Mitosis keeps the number", text="Daughter cells are identical copies, so (a) 46."),
                S("Meiosis halves the number", math=r"46 \div 2 = 23", text="So (b) 23 chromosomes."),
                S("Check with fertilisation", math=r"23 + 23 = 46", text="A sperm and an egg together restore 46."),
            ]),
            EX("Worked example 2: counting cells", intro="One cell divides by mitosis. Each daughter cell divides again, and this continues for five divisions. How many cells are there?", steps=[
                S("Each division doubles the cells", text="After 1 division: 2; after 2: 4; after 3: 8; after 4: 16."),
                S("Use the rule", math=r"2^5 = 32"),
                S("State the answer", text="There are 32 cells after five rounds of mitosis."),
            ]),
            MISTAKE("Mixing up the words 'mitosis' and 'meiosis'", "Link meiosis with 'making gametes, half the chromosomes'. Mitosis is for 'making more cells like the parent'. Write the full word in the exam, never a short form that could be read as either."),
            MISTAKE("Saying that meiosis produces two cells", "Meiosis has two divisions and ends with four cells. Mitosis has one division and two cells."),
            QUIZ("Which stage of mitosis sees chromatids pulled to opposite ends of the cell?", ["Prophase", "Metaphase", "Anaphase", "Telophase"], 2,
                 "In anaphase the spindle fibres shorten and pull the chromatids apart.",
                 hint="Think of 'apart' and 'anaphase'.",
                 feedback=["In prophase the chromosomes first become visible.", "In metaphase the chromosomes line up on the equator.", "", "In telophase new nuclei form."]),
            QUIZ("How many chromosomes does a human egg cell contain?", ["46", "23", "92", "12"], 1,
                 "Meiosis halves the chromosome number from 46 to 23.",
                 hint="Gametes are haploid.",
                 feedback=["46 is the number in a body cell.", "", "92 would be double the normal number.", "12 is not a human gamete number."]),
            TIP("In Paper 1 expect questions on the purpose of each division and on chromosome numbers. In Paper 2 you may be asked to describe mitosis in stages, or to compare mitosis and meiosis. Use the PMAT order and always say what happens to the chromosomes."),
            PQ("State two reasons why human cells divide by mitosis.", "For growth (more cells make the body larger) and for repair or replacement of damaged and worn-out cells."),
            PQ("A cell has 46 chromosomes. How many chromosomes are present in each cell after meiosis?", "23, and four cells are formed."),
            PQ("Explain why gametes are made by meiosis and not by mitosis.", "Meiosis halves the chromosome number. At fertilisation the two gametes join and restore 46. With mitosis the zygote would have 92, and the number would double each generation. Meiosis also gives variation."),
            PQ("List the stages of mitosis in the correct order and describe what happens in anaphase.", "Prophase, metaphase, anaphase, telophase. In anaphase the spindle fibres pull the chromatids to opposite poles."),
            SUM("Cells divide for growth, repair and making gametes.",
                "Human body cells are diploid (46 chromosomes, 23 pairs); gametes are haploid (23).",
                "Mitosis: one division, two identical diploid cells; stages prophase, metaphase, anaphase, telophase.",
                "Meiosis: two divisions, four different haploid cells, only in testes and ovaries.",
                "Fertilisation restores 46: 23 from the sperm and 23 from the egg."),
        ],
    ),
    lesson(
        module=M1, topic="Human tissues",
        title="Human tissues: epithelial, connective, muscular and nervous",
        slug="hbi1-human-tissues", minutes=20,
        summary="Cells of the same kind form a tissue; the human body has four main tissue types (epithelial, connective, muscular and nervous), and tissues combine into organs and organ systems.",
        objectives=["Define tissue, organ and organ system and give the levels of organisation",
                    "Name the four main types of human tissue",
                    "Describe the structure and function of examples of each tissue type",
                    "Match tissues to their locations in the body"],
        key_concepts=["Tissue", "Epithelial tissue", "Connective tissue", "Muscular tissue", "Nervous tissue", "Organ"],
        blocks=[
            H("Introduction"),
            T("A house is built from bricks, but a pile of bricks is not a house. Bricks are joined into walls, walls into rooms and rooms into the house. A human body is built in the same way. One cell cannot do every job, so cells of the same kind are grouped to do one job well."),
            D("A **tissue** is a group of similar cells that work together to do one job. An **organ** is made of several tissues working together, such as the stomach. An **organ system** is a group of organs with a common function, such as the digestive system.", title="Definition"),
            CODE("cell  ->  tissue  ->  organ  ->  organ system  ->  organism", "text", title="Levels of organisation"),
            H("The four main tissues"),
            KEY("Four types of tissue", "Every organ is built from these four.", cards=[
                ["Epithelial", "Cells packed tightly in sheets, with little material between them. They cover and line surfaces. Protect, secrete and absorb."],
                ["Connective", "Cells spread in a large amount of non-living matrix. They support, join and protect, and carry things (blood)."],
                ["Muscular", "Cells that can contract (shorten) to cause movement."],
                ["Nervous", "Neurones that carry electrical impulses to coordinate the body."],
            ]),
            H("Epithelial tissue"),
            T("Epithelium covers the outside of the body (skin) and lines the inside of tubes and cavities (mouth, windpipe, gut). It sits on a thin base layer and has no blood vessels of its own. Different types are adapted to different jobs."),
            CODE("""Type             Shape of cells          Where found            Job
Squamous         Flat, thin              Lining of alveoli,     Easy diffusion of gases;
                                         skin surface           protection
Cuboidal         Cube-shaped             Kidney tubules,        Secretion and absorption
                                         glands
Columnar         Tall, column-like       Lining of the small    Absorption and secretion
                                         intestine, stomach     (mucus)
Ciliated         Columnar with cilia     Windpipe (trachea),    Cilia sweep mucus and dust
                                         bronchi                upwards""", "text", title="Examples of epithelium"),
            H("Connective tissue"),
            T("Connective tissue has cells scattered in a **matrix**, a material made by the cells. The matrix may be fluid, jelly-like or solid, so connective tissues are very different from one another."),
            CODE("""Type                  Matrix                       Job
Blood                 Liquid (plasma)              Transport of gases, food, waste
Bone                  Hard (calcium salts)         Support, protection
Cartilage             Firm, flexible               Smooth surfaces, flexible support
Tendon                Strong fibres (collagen)     Joins muscle to bone
Ligament              Elastic fibres               Joins bone to bone
Adipose (fat)         Small, cells full of fat     Store energy, insulate, cushion
Areolar (loose)       Loose network of fibres      Packs between organs, holds skin to muscle""", "text", title="Examples of connective tissue"),
            H("Muscular and nervous tissue"),
            T("Muscle cells contain protein fibres that slide over each other to shorten the cell. There are three types: **skeletal (striated)** muscle attached to bones and under voluntary control; **smooth (involuntary)** muscle in the walls of the gut and blood vessels; **cardiac** muscle of the heart, which contracts without tiring. Nervous tissue is made of **neurones**, long cells that carry impulses, and supporting cells."),
            H("Worked examples"),
            EX("Worked example 1: identify the tissue", intro="A tissue is made of flat cells in a thin layer and lines the air sacs in the lung. Name it and explain its adaptation.", steps=[
                S("Identify", text="Flat cells in a layer: squamous epithelium."),
                S("Link to the job", text="Gases must diffuse across the lining quickly."),
                S("State the adaptation", text="The cells are very thin (one cell thick), so the diffusion distance is short."),
            ]),
            EX("Worked example 2: from cell to organism", intro="Place these in order from the smallest to the largest: stomach, muscle cell, digestive system, smooth muscle tissue.", steps=[
                S("Find the cell", text="Muscle cell is the smallest."),
                S("Group cells", text="Smooth muscle tissue is a group of muscle cells."),
                S("Group tissues, then organs", text="The stomach (organ) contains muscle, epithelium and others; the digestive system contains the stomach and other organs."),
                S("Final order", text="Muscle cell, smooth muscle tissue, stomach, digestive system."),
            ]),
            MISTAKE("Calling blood 'not a tissue' because it is a liquid", "Blood is a connective tissue. Its matrix is the liquid plasma and the cells are suspended in it."),
            MISTAKE("Mixing up tendon and ligament", "A tendon joins muscle to bone. A ligament joins bone to bone. Remember 'T for tendon, T for tie muscle to bone'."),
            QUIZ("Which tissue lines the windpipe and sweeps dust and mucus upwards?", ["Squamous epithelium", "Ciliated epithelium", "Adipose tissue", "Smooth muscle"], 1,
                 "Ciliated epithelium has hair-like cilia that beat to move mucus.",
                 hint="Look for cilia.",
                 feedback=["Squamous cells are flat and have no cilia.", "", "Adipose tissue stores fat.", "Smooth muscle contracts to move food and does not sweep mucus."]),
            QUIZ("Bone, blood and cartilage all belong to which type of tissue?", ["Epithelial", "Muscular", "Nervous", "Connective"], 3,
                 "They all have cells in a matrix, which defines connective tissue.",
                 hint="Think of the matrix.",
                 feedback=["Epithelial cells are tightly packed.", "Muscle contracts.", "Nervous tissue carries impulses.", ""]),
            TIP("This topic appears in Paper 1 as 'which tissue does X' or 'where is tissue Y found'. In Paper 2 (cells and tissues are tested directly), define a tissue and give an example of each type with its place and function."),
            PQ("Define a tissue and give two examples.", "A tissue is a group of similar cells that carry out the same job. Examples: smooth muscle, epithelium, bone, blood (any two)."),
            PQ("State where each is found: (a) cardiac muscle, (b) columnar epithelium, (c) cartilage.", "(a) The wall of the heart. (b) The lining of the small intestine and stomach. (c) The ear pinna, the nose, the ends of bones, the trachea or between vertebrae (any one)."),
            PQ("Describe how the structure of a neurone suits its function.", "It is long, with fibres that carry electrical impulses over long distances quickly from one part of the body to another."),
            PQ("Name the type of tissue (a) that covers the skin, (b) with a liquid matrix, (c) that causes movement.", "(a) Epithelial tissue. (b) Connective tissue (blood). (c) Muscular tissue."),
            SUM("A tissue is a group of similar cells with one job; tissues form organs and organs form systems.",
                "Epithelial tissue covers and lines surfaces; squamous, cuboidal, columnar and ciliated are examples.",
                "Connective tissue has cells in a matrix: blood, bone, cartilage, tendons, ligaments and fat.",
                "Muscular tissue contracts: skeletal, smooth and cardiac.",
                "Nervous tissue is made of neurones that carry impulses."),
        ],
    ),
    lesson(
        module=M1, topic="Biochemistry of food nutrients",
        title="Carbohydrates, lipids and proteins: the chemistry of food",
        slug="hbi1-food-biochemistry", minutes=22,
        summary="Carbohydrates, lipids and proteins are large molecules built from small units: sugars, fatty acids with glycerol, and amino acids; each has its own elements, structure and uses in the body.",
        objectives=["Name the elements in carbohydrates, lipids and proteins",
                    "Describe how simple units join to make larger molecules",
                    "State the functions of carbohydrates, lipids, proteins, vitamins, minerals, water and fibre",
                    "Compare the energy values of the main food nutrients"],
        key_concepts=["Carbohydrate", "Glucose", "Lipid", "Protein", "Amino acid", "Monomer and polymer"],
        blocks=[
            H("Introduction"),
            T("A plate of cassava, beans and palm oil gives you three main kinds of food: starch, protein and fat. They look very different, but each is built in a similar way: **small units joined together to make a large molecule**. In this lesson you look at the chemistry of these foods, which prepares you for digestion and food tests in later lessons."),
            D("A **nutrient** is a substance in food that the body needs. The main nutrients are carbohydrates, lipids (fats and oils), proteins, vitamins, mineral salts, water and fibre (roughage).", title="Definition"),
            H("Carbohydrates"),
            T("Carbohydrates contain the elements **carbon, hydrogen and oxygen**. They are made of sugar units. Glucose has the formula C6H12O6."),
            CODE("""Type            Units                  Examples                  Found in
Monosaccharide  1 sugar unit           Glucose, fructose         Fruit, honey
Disaccharide    2 units joined         Maltose, sucrose, lactose Sugar cane, milk, germinating seeds
Polysaccharide  Many units joined      Starch, glycogen,         Cassava, yam, maize,
                                       cellulose                 plantain; liver and muscle; plant cell walls""", "text", title="Types of carbohydrate"),
            T("Two glucose molecules join to form maltose, and a molecule of water is released: glucose + glucose gives maltose + water. This kind of reaction is called condensation. In the reverse reaction, a molecule of water is added to split a large molecule into small ones. This is called hydrolysis, which is what happens in digestion."),
            T("Carbohydrates are the main source of energy. Glucose is the fuel of respiration. Starch is the storage form in plants. Glycogen is stored in the human liver and muscles. Cellulose is not digested by humans but forms fibre."),
            H("Lipids"),
            T("Lipids (fats and oils) also contain **carbon, hydrogen and oxygen**, but with much less oxygen than carbohydrates. A lipid molecule is made of **one glycerol and three fatty acids**. Fats are solid at room temperature; oils are liquid (palm oil, groundnut oil, fish oil). Lipids are insoluble in water."),
            T("Lipids give twice as much energy per gram as carbohydrate. The body stores fat under the skin as a reserve of energy and as insulation against heat loss. Fat also protects organs such as the kidneys, and is needed for cell membranes and for taking up vitamins A, D, E and K."),
            H("Proteins"),
            T("Proteins contain **carbon, hydrogen, oxygen and nitrogen**, and some contain sulphur. They are long chains of **amino acids**. There are about 20 different amino acids, and the order in which they are joined decides the kind of protein. The links between them are called peptide bonds."),
            T("Proteins are needed for growth and repair of tissue. Many hormones, antibodies and all enzymes are proteins. Muscles, hair and skin are mostly protein. Good sources include fish, meat, eggs, beans, groundnuts and soya. Protein can also be used as an energy source when fats and carbohydrates are not available."),
            KEY("Building blocks", "Memorise this chain of ideas.", cards=[
                ["Carbohydrate", "Many sugar units (glucose) joined: starch, glycogen, cellulose. Elements C, H, O."],
                ["Lipid", "Glycerol plus three fatty acids. Elements C, H, O."],
                ["Protein", "Many amino acids joined by peptide bonds. Elements C, H, O, N (and sometimes S)."],
            ]),
            H("Other nutrients"),
            T("**Vitamins** are needed in very small amounts for health, for example vitamin C (stops scurvy) and vitamin D (healthy bones). **Mineral salts** such as calcium (bones and teeth), iron (haemoglobin) and iodine (thyroid hormone) are also needed in small amounts. **Water** is the solvent for chemical reactions and for transport in blood. **Fibre** helps food move through the gut and prevents constipation."),
            H("Energy values"),
            T("Energy in food is measured in kilojoules (kJ). Many textbooks give about 17 kJ per gram for carbohydrate and for protein, and about 37 kJ per gram for fat (check your textbook, because figures vary slightly)."),
            EX("Worked example 1: energy from a meal", intro="Use 17 kJ per gram for carbohydrate, 17 kJ per gram for protein and 37 kJ per gram for fat. A snack contains 30 g carbohydrate, 10 g protein and 20 g fat. Find the total energy.", steps=[
                S("Carbohydrate", math=r"30 \times 17 = 510\ \text{kJ}"),
                S("Protein", math=r"10 \times 17 = 170\ \text{kJ}"),
                S("Fat", math=r"20 \times 37 = 740\ \text{kJ}"),
                S("Add", math=r"510 + 170 + 740 = 1420\ \text{kJ}"),
            ]),
            EX("Worked example 2: which nutrient?", intro="A food sample contains the elements C, H, O and N. Which nutrient is it likely to be, and why?", steps=[
                S("Look for nitrogen", text="Only proteins contain nitrogen out of the three main groups."),
                S("State the answer", text="The sample is a protein; it is made of amino acids."),
            ]),
            MISTAKE("Saying carbohydrates and lipids have different elements", "Both are made of carbon, hydrogen and oxygen. The difference is the proportion: lipids have far less oxygen. Only proteins add nitrogen."),
            MISTAKE("Writing that fat is not needed in the diet", "The body needs some fat for energy storage, insulation, protection and to take in fat-soluble vitamins. The mistake is too much fat, not fat itself."),
            QUIZ("Which of these is made of amino acids?", ["Starch", "Palm oil", "Haemoglobin", "Glucose"], 2,
                 "Haemoglobin is a protein, so it is made of amino acids.",
                 hint="Which of these contains nitrogen?",
                 feedback=["Starch is made of glucose units.", "Palm oil is a lipid made of glycerol and fatty acids.", "", "Glucose is a simple sugar, a monomer itself."]),
            QUIZ("A lipid molecule is made of", ["three amino acids", "glycerol and three fatty acids", "glucose and fructose", "two glucose units"], 1,
                 "A lipid has one glycerol joined to three fatty acids.",
                 hint="Fats do not contain nitrogen or sugar units.",
                 feedback=["Amino acids make proteins.", "", "Glucose and fructose make sucrose, a disaccharide.", "Two glucose units make maltose."]),
            TIP("In Paper 1, this topic is often tested by 'which elements are in...' and 'which nutrient is used for...'. In essays, name the nutrient, say where it comes from (a food), and state its function."),
            PQ("Name the elements found in (a) carbohydrates and (b) proteins.", "(a) Carbon, hydrogen and oxygen. (b) Carbon, hydrogen, oxygen and nitrogen (sometimes sulphur)."),
            PQ("Name the end products when a fat is completely digested.", "Glycerol and fatty acids."),
            PQ("State two uses of fat in the human body.", "Energy store; insulation against heat loss; protects organs; part of cell membranes; helps to take up vitamins A, D, E, K. Any two."),
            PQ("Calculate the energy from 50 g of fat, using 37 kJ per gram.", "50 x 37 = 1850 kJ."),
            SUM("Nutrients are carbohydrates, lipids, proteins, vitamins, minerals, water and fibre.",
                "Carbohydrates (C, H, O) are sugar units joined; they are the main energy source.",
                "Lipids (C, H, O) are glycerol with three fatty acids; they store energy and insulate.",
                "Proteins (C, H, O, N) are chains of amino acids; they build and repair tissue and form enzymes.",
                "Fat gives about 37 kJ per gram, carbohydrate and protein about 17 kJ per gram (check your textbook)."),
        ],
    ),
    lesson(
        module=M1, topic="Enzyme action",
        title="Enzymes: biological catalysts",
        slug="hbi1-enzyme-action", minutes=20,
        summary="Enzymes are protein catalysts that speed up reactions in cells; each acts on one substrate at its active site, and works best at its optimum temperature and pH, but is denatured by high temperature.",
        objectives=["Define an enzyme and a catalyst",
                    "Explain enzyme action using the lock-and-key model",
                    "Describe the effect of temperature and pH on enzyme activity",
                    "Interpret a graph of enzyme activity"],
        key_concepts=["Enzyme", "Substrate", "Active site", "Specificity", "Optimum", "Denaturation"],
        blocks=[
            H("Introduction"),
            T("A cassava root takes hours to break down in a fire but your body digests starch in minutes at only 37 degrees Celsius. The difference is that your body uses enzymes. Without enzymes, the reactions of life would be too slow to keep us alive."),
            D("An **enzyme** is a protein that works as a biological **catalyst**: it speeds up a chemical reaction without being used up or changed. The substance on which an enzyme acts is the **substrate**, and what it makes is the **product**.", title="Definition"),
            H("Properties of enzymes"),
            KEY("Remember these properties", "They are all examined.", cards=[
                ["Proteins", "Enzymes are made of protein, so they are destroyed by heat."],
                ["Catalysts", "They are not used up and can be used again and again."],
                ["Specific", "Each enzyme works on one kind of substrate only, for example amylase acts only on starch."],
                ["Sensitive", "Their action depends on temperature and pH."],
                ["Needed in small amounts", "A little enzyme can change a lot of substrate."],
            ]),
            H("How an enzyme works: lock and key"),
            T("An enzyme has a special area called the **active site**, with a particular shape. Only a substrate with the matching shape fits into it, like a key in a lock. The substrate and the enzyme join to form an **enzyme-substrate complex**, the reaction takes place, the products leave, and the enzyme is free to work again."),
            IMG("f5hbi1-enzyme-lock.svg", alt="Three-stage diagram: substrate meets active site, forms a complex, products leave with the enzyme unchanged", caption="Figure 1. The lock-and-key model of enzyme action (schematic)."),
            T("This explains specificity. If the shape of the substrate does not match the active site, the reaction does not take place."),
            H("Effect of temperature and pH"),
            T("At low temperature the particles move slowly, so there are few collisions between enzyme and substrate and the reaction is slow. As temperature rises, the rate increases until the **optimum temperature** is reached, which is about 37 degrees Celsius for most human enzymes. Above about 45 to 50 degrees, the enzyme loses its shape: the active site is changed and the substrate no longer fits. The enzyme is **denatured**. This change is permanent, and cooling does not restore it."),
            IMG("f5hbi1-enzyme-temp.svg", alt="Graph of rate of reaction against temperature: rises to an optimum then falls steeply as the enzyme is denatured", caption="Figure 2. Rate of an enzyme reaction at different temperatures (schematic)."),
            T("Each enzyme also has an **optimum pH**. Salivary amylase and most enzymes in the cells work best near neutral pH. Pepsin in the stomach works best in acid (about pH 2), and enzymes in the small intestine prefer a slightly alkaline pH. Very high or very low pH can also denature an enzyme."),
            H("Worked examples"),
            EX("Worked example 1: using a graph", intro="A student measures how many millilitres of product an enzyme makes in 5 minutes at different temperatures (practice figures invented): 10 degrees, 5 mL; 20 degrees, 12 mL; 30 degrees, 25 mL; 37 degrees, 40 mL; 50 degrees, 4 mL. Find the rate at 37 degrees in mL per minute and explain the result at 50 degrees.", steps=[
                S("Rate = product / time", math=r"\frac{40}{5} = 8\ \text{mL per minute}"),
                S("Look at 50 degrees", text="The product drops to 4 mL."),
                S("Explain", text="At 50 degrees the enzyme is denatured, so the active site no longer fits the substrate."),
            ]),
            EX("Worked example 2: explain why boiling stops digestion", intro="Why does boiled saliva fail to digest starch?", steps=[
                S("State what boiling does", text="Boiling destroys the shape of proteins."),
                S("Apply to the enzyme", text="Amylase in saliva is a protein, so it is denatured and its active site is lost."),
                S("Conclude", text="Starch is not digested, and cooling the saliva does not bring the enzyme back."),
            ]),
            MISTAKE("Saying enzymes are 'killed' by heat", "Enzymes are not living, so they cannot be killed. They are denatured: the shape of the protein changes permanently."),
            MISTAKE("Saying low temperature denatures enzymes", "Cold only slows enzymes down. They work again when warmed. Only high temperatures denature."),
            QUIZ("Which statement about enzymes is correct?", ["They are used up in the reaction", "They work on any substrate", "They are proteins", "They work best at 100 degrees"], 2,
                 "Enzymes are proteins. They are reusable, specific and denatured by high temperatures.",
                 hint="Think about what happens to an egg white when you heat it.",
                 feedback=["Enzymes are catalysts and are not used up.", "Each enzyme is specific.", "", "100 degrees would denature a human enzyme."]),
            QUIZ("The graph of enzyme rate against temperature falls steeply above the optimum because", ["there is less substrate", "the enzyme is denatured", "the enzyme is made of fat", "the particles slow down"], 1,
                 "Heat changes the shape of the protein, so the active site does not fit any more.",
                 hint="Compare with what happens when you boil an egg.",
                 feedback=["The substrate is the same amount.", "", "Enzymes are proteins, not fats.", "Particles move faster, not slower, at high temperature."]),
            TIP("Paper 1 tests the properties of enzymes and graph reading. In Paper 2, you may need to explain a graph in words: describe the rise, the peak (optimum), and the fall (denaturation) with reasons."),
            PQ("Define an enzyme.", "A protein that acts as a biological catalyst, speeding up a chemical reaction without being changed or used up."),
            PQ("Why does an enzyme act only on one substrate?", "The shape of the active site matches only one substrate (lock and key), so other molecules do not fit."),
            PQ("Describe and explain what happens to the activity of an enzyme as temperature is raised from 0 to 60 degrees Celsius.", "The rate increases because the particles collide more often, up to the optimum (about 37 degrees). Beyond it the rate falls quickly because the enzyme is denatured and the active site changes shape. At 60 degrees there is no activity."),
            PQ("Name one enzyme that works in acid conditions and one in the mouth.", "Pepsin works in the stomach in acid; salivary amylase works in the mouth."),
            SUM("Enzymes are protein catalysts that speed up reactions and are not used up.",
                "The substrate fits the active site (lock and key): each enzyme is specific.",
                "Rate increases with temperature up to the optimum, about 37 degrees Celsius for human enzymes.",
                "High temperature or extreme pH denatures an enzyme permanently.",
                "Cold slows enzymes but does not destroy them."),
        ],
    ),
    lesson(
        module=M2, topic="Bone and cartilage",
        title="Bone and cartilage: structure and functions",
        slug="hbi1-bone-cartilage", minutes=20,
        summary="Bone is a hard living tissue made of calcium salts for strength and collagen for flexibility; cartilage is a firm but flexible tissue without blood vessels found at joints, the ear and nose.",
        objectives=["State the functions of the skeleton",
                    "Describe the composition and structure of bone",
                    "Compare compact and spongy bone, and red and yellow marrow",
                    "Describe the structure, functions and places of cartilage"],
        key_concepts=["Bone", "Calcium phosphate", "Collagen", "Bone marrow", "Cartilage", "Periosteum"],
        blocks=[
            H("Introduction"),
            T("A fall from a mango tree can break a child's arm, yet a leg bone can carry an adult carrying a bag of cement. Bone is strong, but not like a stone. It is a living tissue with blood vessels and cells, and it grows and mends itself."),
            T("The skeleton has five functions. It gives **support** to the body, **protects** soft organs (the skull protects the brain, the ribs protect the heart and lungs), allows **movement** (muscles pull on bones), makes **blood cells** in bone marrow, and **stores minerals** such as calcium and phosphate."),
            H("What bone is made of"),
            D("**Bone** is a connective tissue. Its matrix contains **calcium phosphate** (a mineral that makes bone hard and strong) and **collagen** (a protein fibre that makes it slightly flexible and prevents it from being brittle). Living **bone cells** (osteocytes) are embedded in the matrix and supplied by blood vessels.", title="Definition"),
            T("A simple experiment shows this. If a clean chicken bone is soaked in dilute acid for a few days, the calcium salts dissolve and the bone becomes soft and rubbery and can be bent or tied in a knot. If another bone is heated strongly in a fire, the protein burns away and the bone becomes brittle and breaks easily. So the minerals give hardness and the protein gives flexibility."),
            H("Structure of a long bone"),
            KEY("Parts of a long bone such as the femur", "From outside to inside.", cards=[
                ["Periosteum", "A tough outer membrane with blood vessels and nerves; it helps growth and healing, and tendons attach to it."],
                ["Compact bone", "Hard, dense bone forming the shaft. It resists bending."],
                ["Spongy bone", "A honeycomb of thin bony struts at the ends of the bone. It is light and absorbs shock."],
                ["Bone marrow", "Fills the marrow cavity and the spaces of spongy bone. Red marrow makes red blood cells; yellow marrow stores fat."],
            ]),
            T("A hollow shaft is nearly as strong as a solid rod but much lighter, so the skeleton is not too heavy to move."),
            H("Cartilage"),
            D("**Cartilage** is a firm, smooth and flexible connective tissue. It has a matrix of collagen (and elastic fibres) with cells called chondrocytes. It has **no blood vessels** and is not hard like bone.", title="Definition"),
            CODE("""Where found                      Job
Ends of bones in joints          Smooth surface, reduces friction, absorbs shock
Between vertebrae (discs)        Cushions, allows the back to bend
Ear pinna and tip of the nose    Shape and support while staying flexible
Rings in the trachea             Keep the airway open
Ribs (joining to the sternum)    Allows the chest to move in breathing""", "text", title="Cartilage in the body"),
            T("In an unborn baby most of the skeleton is cartilage. During childhood much of it is replaced by bone, which is called **ossification**, as calcium salts are added. This is the reason a child's bones are more flexible and why enough calcium and vitamin D in the diet is needed for growth."),
            CODE("""Feature          Bone                         Cartilage
Hardness         Hard                         Firm but flexible
Matrix           Collagen + calcium phosphate Collagen (and elastic fibres)
Blood supply     Yes                          None
Heals            Fairly quickly               Very slowly""", "text", title="Bone compared with cartilage"),
            H("Worked examples"),
            EX("Worked example 1: what the acid does", intro="A bone soaked in acid for three days can be bent easily. Explain.", steps=[
                S("Name what acid does", text="Acid reacts with and dissolves calcium phosphate."),
                S("Name what remains", text="Only the collagen is left, which is flexible."),
                S("Conclude", text="The bone is rubbery because the hardness (minerals) has been removed."),
            ]),
            EX("Worked example 2: why spongy bone at the ends", intro="Why is the end of a long bone made of spongy bone and not compact bone?", steps=[
                S("Describe spongy bone", text="It has a honeycomb structure with spaces filled with marrow."),
                S("Link to function", text="It is lighter than compact bone and spreads and absorbs the load from the joint."),
                S("Add the role of marrow", text="The spaces are also where red marrow makes blood cells."),
            ]),
            MISTAKE("Saying bone is dead and hard like stone", "Bone is living. It has blood vessels and cells, grows, and repairs itself."),
            MISTAKE("Writing that cartilage has a blood supply", "Cartilage has no blood vessels. It gets food by diffusion, so it heals very slowly."),
            QUIZ("Which substance gives bone its hardness?", ["Collagen", "Calcium phosphate", "Fat", "Marrow"], 1,
                 "Calcium phosphate makes bone hard; collagen adds flexibility.",
                 hint="What do we need from milk and sunlight for bones?",
                 feedback=["Collagen gives flexibility.", "", "Fat is stored in yellow marrow.", "Marrow is soft and makes blood cells."]),
            QUIZ("Where are red blood cells made in an adult?", ["Periosteum", "Compact bone", "Red bone marrow", "Cartilage"], 2,
                 "Red blood cells are made in red marrow, in spongy bone of flat bones and the ends of long bones.",
                 hint="Marrow in two colours.",
                 feedback=["The periosteum is the outer membrane.", "Compact bone is the dense shaft.", "", "Cartilage has no blood cell production."]),
            TIP("This topic belongs to the 'Skeletal system' question in Paper 2, which the Board's 2023 report calls a straightforward question. Learn the five functions of the skeleton, the structure of a long bone and the differences between bone and cartilage."),
            PQ("State four functions of the skeleton.", "Support; protection of organs; movement (with muscles); production of blood cells; storage of calcium and phosphate. Any four."),
            PQ("Name the two main components of bone and state the function of each.", "Calcium phosphate gives hardness and strength; collagen gives flexibility and prevents brittleness."),
            PQ("Give three places where cartilage is found in the human body.", "Ends of bones at joints; between vertebrae; ear pinna; nose; trachea; ribs. Any three."),
            PQ("Explain why a child's bone is more flexible than an old person's.", "A child's bones have more cartilage and proportionally more collagen; the proportion of mineral is lower. In older people minerals can be lost, so bones become brittle."),
            SUM("The skeleton supports, protects, allows movement, makes blood cells and stores minerals.",
                "Bone is a living tissue: calcium phosphate makes it hard and collagen makes it flexible.",
                "A long bone has periosteum, compact bone, spongy bone and marrow.",
                "Cartilage is firm, flexible and without blood vessels: ear, nose, joints, discs, trachea.",
                "Most of a baby's skeleton is cartilage; it becomes bone by ossification."),
        ],
    ),
    lesson(
        module=M2, topic="The skeleton",
        title="The skeleton: axial and appendicular, and the vertebral column",
        slug="hbi1-skeleton", minutes=24,
        summary="The adult skeleton has 206 bones in two parts: the axial skeleton (skull, vertebral column, ribs, sternum) and the appendicular skeleton (limbs and girdles); the vertebral column has five regions of vertebrae.",
        objectives=["Distinguish the axial skeleton from the appendicular skeleton",
                    "Name the main bones of the skull, trunk, arm and leg",
                    "Describe the regions and a typical vertebra",
                    "Relate the structure of the atlas and axis to head movement"],
        key_concepts=["Axial skeleton", "Appendicular skeleton", "Girdle", "Vertebral column", "Atlas and axis", "Rib cage"],
        blocks=[
            H("Introduction"),
            T("When a footballer in Yaounde heads the ball, the neck bones take the shock. When he kicks, the leg bones, hip bones and back work together. To know how the body moves you must first know the bones."),
            T("An adult human skeleton has **206 bones**. It is divided into two parts."),
            KEY("Two parts of the skeleton", "Axis and appendages.", cards=[
                ["Axial skeleton (80 bones)", "The skull, the vertebral column, the ribs and the sternum (breastbone). It forms the main axis of the body."],
                ["Appendicular skeleton (126 bones)", "The bones of the arms and legs and the girdles that join them to the axial skeleton: the pectoral (shoulder) girdle and the pelvic (hip) girdle."],
            ]),
            IMG("f5hbi1-skeleton.svg", alt="Labelled front view of the human skeleton", caption="Figure 1. The human skeleton (schematic, front view)."),
            H("Skull, ribs and sternum"),
            T("The **skull** has the cranium, which protects the brain, and the facial bones. The only movable bone in the skull is the lower jaw (mandible). The **ribs** are 12 pairs. They join the thoracic vertebrae at the back, and the upper ones join the sternum at the front by cartilage. The ribs and sternum form the rib cage, which protects the heart and lungs and moves in breathing. The upper seven pairs join the sternum directly; the next three pairs join the rib above; the last two pairs are the floating ribs, which end freely."),
            H("The girdles and limbs"),
            T("The **pectoral girdle** is made of two clavicles (collar bones) and two scapulae (shoulder blades). It is loosely attached to the trunk, which allows the arm a very wide range of movements. The **pelvic girdle** is made of two hip bones, joined to each other at the front and to the sacrum at the back. It is strongly fixed to the backbone, to carry the weight of the body, and it protects the organs in the lower abdomen."),
            CODE("""Region          Arm (forelimb)                  Leg (hindlimb)
Upper           Humerus (1 bone)                Femur (1 bone)
Middle          Radius and ulna (2 bones)       Tibia and fibula (2 bones)
Joint cap       -                               Patella (kneecap)
Wrist / ankle   Carpals                         Tarsals
Hand / foot     Metacarpals                     Metatarsals
Digits          Phalanges                       Phalanges""", "text", title="Limb bones"),
            T("The femur is the longest and strongest bone in the body. The tibia carries the weight of the lower leg; the fibula is thin and gives attachment to muscle."),
            H("The vertebral column"),
            T("The vertebral column (backbone) is made of 33 bones called **vertebrae**, in five regions. Some are separate; the sacral and coccygeal vertebrae fuse during growth. The vertebrae are separated by pads of cartilage (intervertebral discs), which absorb shock and allow bending."),
            CODE("""Region        Number   Notes
Cervical      7        Neck. First two are the atlas and axis
Thoracic      12       Chest. Each carries a pair of ribs
Lumbar        5        Lower back. Largest, carry most weight
Sacral        5        Fused to form the sacrum, joined to the hip bones
Coccygeal     4        Fused to form the coccyx (tail bone)""", "text", title="Regions of the backbone"),
            T("A typical vertebra has a solid **centrum** at the front, which takes the weight; a **neural arch** that encloses the **neural canal**, through which the spinal cord passes; a **spinous process** at the back and two **transverse processes** at the sides, where muscles attach. The atlas (the first cervical vertebra) supports the skull and allows the head to nod (the 'yes' movement). The axis (the second cervical vertebra) has a peg (the odontoid process) around which the atlas turns, so the head can rotate (the 'no' movement)."),
            EX("Worked example 1: count the bones", intro="Check that the vertebral column has 33 vertebrae, and that 80 axial plus 126 appendicular bones give 206.", steps=[
                S("Add the regions", math=r"7 + 12 + 5 + 5 + 4 = 33"),
                S("Add the two parts", math=r"80 + 126 = 206"),
                S("State the result", text="Both totals are correct."),
            ]),
            EX("Worked example 2: classify the bones", intro="Classify these as axial or appendicular: femur, sternum, scapula, atlas, humerus.", steps=[
                S("Find those on the axis", text="Sternum and atlas are in the axial skeleton (chest and backbone)."),
                S("Find limbs and girdles", text="Femur, scapula (pectoral girdle) and humerus are in the appendicular skeleton."),
            ]),
            MISTAKE("Mixing up radius and ulna with tibia and fibula", "The arm has humerus, radius and ulna. The leg has femur, tibia and fibula. The names of the two pairs are not interchangeable."),
            MISTAKE("Saying the sternum is a vertebra", "The sternum is the flat breastbone at the front of the chest. Vertebrae are in the backbone."),
            QUIZ("Which bone forms part of the pectoral girdle?", ["Femur", "Scapula", "Sacrum", "Patella"], 1,
                 "The pectoral girdle has the clavicle and scapula.",
                 hint="Which is the shoulder blade?",
                 feedback=["The femur is a leg bone.", "", "The sacrum belongs to the backbone and pelvis.", "The patella is the kneecap."]),
            QUIZ("The vertebra that allows the head to rotate from side to side is the", ["atlas", "axis", "coccyx", "sacrum"], 1,
                 "The atlas turns around the peg of the axis, giving rotation. The atlas alone allows nodding.",
                 hint="Think of the peg.",
                 feedback=["The atlas supports the skull and allows nodding.", "", "The coccyx is the tail bone and cannot rotate the head.", "The sacrum is at the base of the spine."]),
            TIP("Learn the names of the main bones, and be able to say whether each belongs to the axial or appendicular skeleton. For diagrams, practise labelling an unlabelled skeleton, and describe a typical vertebra with its neural canal."),
            PQ("Name the five regions of the vertebral column and give the number of vertebrae in each.", "Cervical 7, thoracic 12, lumbar 5, sacral 5 (fused), coccygeal 4 (fused)."),
            PQ("Name the bones of the forelimb from the shoulder to the fingers.", "Humerus, radius and ulna, carpals, metacarpals, phalanges."),
            PQ("State two functions of the rib cage.", "Protects the heart and lungs; its movement helps breathing."),
            PQ("Describe a typical vertebra and the job of the neural canal.", "A centrum at the front, a neural arch above it with a spinous process and two transverse processes. The neural canal inside the arch protects the spinal cord."),
            SUM("The adult skeleton has 206 bones: 80 axial and 126 appendicular.",
                "The axial skeleton is skull, vertebral column, ribs and sternum.",
                "The appendicular skeleton is the limbs plus the pectoral and pelvic girdles.",
                "The backbone has 7 cervical, 12 thoracic, 5 lumbar, 5 sacral and 4 coccygeal vertebrae (33 in all).",
                "Atlas and axis allow nodding and turning of the head."),
        ],
    ),
    lesson(
        module=M2, topic="Joints",
        title="Joints: fixed, slightly movable and synovial",
        slug="hbi1-joints", minutes=20,
        summary="A joint is where two bones meet: fixed joints do not move, slightly movable joints move a little, and synovial joints (ball-and-socket, hinge, pivot, gliding) move freely, cushioned by cartilage and lubricated by synovial fluid.",
        objectives=["Define a joint and name the three groups of joints",
                    "Label the parts of a synovial joint and state their functions",
                    "Compare ball-and-socket and hinge joints and give examples",
                    "Distinguish a ligament from a tendon"],
        key_concepts=["Joint", "Synovial joint", "Ball-and-socket joint", "Hinge joint", "Ligament", "Synovial fluid"],
        blocks=[
            H("Introduction"),
            T("A footballer swings his leg at the hip, bends his knee, and turns his head to look for a pass. Each of these movements takes place at a different kind of joint. Without joints the skeleton would be a rigid frame, unable to move."),
            D("A **joint** is a place where two or more bones meet.", title="Definition"),
            H("Three groups of joints"),
            KEY("Types of joint by movement", "From no movement to free movement.", cards=[
                ["Fixed (immovable)", "The bones are tightly joined by fibres and do not move. Example: the sutures between the bones of the skull, which protect the brain."],
                ["Slightly movable", "Bones are separated by pads of cartilage, and allow a small movement. Example: between the vertebrae; the ribs and sternum."],
                ["Synovial (freely movable)", "A fluid-filled space allows large movement. Examples: shoulder, hip, elbow, knee, wrist."],
            ]),
            H("The synovial joint"),
            IMG("f5hbi1-synovial-joint.svg", alt="Labelled section through a synovial joint with bone ends, articular cartilage, synovial fluid, synovial membrane, capsule and ligaments", caption="Figure 1. A synovial joint (schematic section)."),
            CODE("""Part                    Structure                       Function
Articular cartilage     Smooth cartilage on bone ends   Reduces friction, absorbs shock
Synovial fluid          Slippery fluid in the cavity    Lubricates the joint, supplies food to cartilage
Synovial membrane       Lining of the capsule           Makes the synovial fluid
Capsule                 Tough fibrous sleeve            Holds the joint together, encloses the fluid
Ligaments               Strong elastic fibres           Join bone to bone, prevent dislocation""", "text", title="Parts of a synovial joint"),
            D("A **ligament** joins **bone to bone**. A **tendon** joins **muscle to bone**. Ligaments are slightly elastic; tendons are strong and do not stretch.", title="Definition"),
            H("Kinds of synovial joint"),
            CODE("""Type                Movement                           Examples
Ball-and-socket     All directions, plus rotation      Shoulder, hip
Hinge               Back and forth in one plane        Elbow, knee, fingers, ankle
Pivot               Rotation                           Atlas and axis (turning the head);
                                                       radius and ulna (turning the forearm)
Gliding             Sliding of flat surfaces           Wrist, between vertebrae""", "text", title="Types of synovial joint"),
            T("In a **ball-and-socket joint** the rounded head of one bone fits into a cup of another. It is the most movable type, but it is less stable. In a **hinge joint** the bone ends fit together like a door hinge, so that movement is in one plane only. A hinge joint is more stable, which is why the knee carries the weight of the body."),
            H("Worked examples"),
            EX("Worked example 1: choose the joint", intro="Which kind of joint allows a goalkeeper to swing his arm in a full circle, and why can his elbow not do this?", steps=[
                S("Name the shoulder joint", text="A ball-and-socket joint: the round head of the humerus fits into the socket of the scapula."),
                S("Describe its movement", text="It allows movement in all directions and rotation."),
                S("Explain the elbow", text="The elbow is a hinge joint, which allows bending and straightening in one plane only."),
            ]),
            EX("Worked example 2: why bones do not wear away", intro="Explain why the bones at a knee do not wear away when a person walks every day.", steps=[
                S("Mention the cartilage", text="The ends of the bones are covered by smooth articular cartilage that reduces friction and absorbs shock."),
                S("Mention the fluid", text="Synovial fluid in the joint cavity lubricates the surfaces like oil."),
                S("Mention the ligaments", text="Ligaments hold the bones in position so that they move in the correct way."),
            ]),
            MISTAKE("Saying that a ligament joins muscle to bone", "That is a tendon. A ligament connects bone to bone. Write both words with their definitions when the question asks for a difference."),
            MISTAKE("Naming the knee as a ball-and-socket joint", "The knee moves in one plane, so it is a hinge joint. Shoulder and hip are the ball-and-socket joints."),
            QUIZ("The fluid inside a synovial joint is produced by the", ["articular cartilage", "ligament", "synovial membrane", "tendon"], 2,
                 "The synovial membrane lines the capsule and secretes synovial fluid.",
                 hint="The fluid and the membrane share a name.",
                 feedback=["Cartilage covers the bone ends but does not make the fluid.", "Ligaments hold bones together.", "", "Tendons join muscles to bones."]),
            QUIZ("Which pair of joints are both ball-and-socket?", ["Elbow and knee", "Shoulder and hip", "Wrist and ankle", "Atlas and knee"], 1,
                 "Shoulder and hip are ball-and-socket joints.",
                 hint="These two allow rotation in many directions.",
                 feedback=["Elbow and knee are hinge joints.", "", "Wrist is gliding and the ankle is a hinge.", "The atlas-axis joint is a pivot and the knee is a hinge."]),
            TIP("Learn the names of the parts of a synovial joint with the job of each, and be ready to label an unlabelled diagram. In Paper 1, expect 'which joint allows rotation?' and 'what is the function of synovial fluid?'. Say 'bone to bone' for ligaments and 'muscle to bone' for tendons."),
            PQ("Name three types of joint and give one example of each.", "Fixed: skull sutures. Slightly movable: between vertebrae. Synovial: shoulder, hip, elbow or knee."),
            PQ("State the functions of (a) synovial fluid, (b) articular cartilage, (c) ligaments.", "(a) Lubricates the joint and feeds the cartilage. (b) Reduces friction and absorbs shock. (c) Join bone to bone and hold the joint in position."),
            PQ("Give two differences between a ball-and-socket joint and a hinge joint.", "Ball and socket moves in all directions with rotation (e.g. hip); a hinge moves in one plane only (e.g. knee). Ball and socket is less stable; a hinge is more stable."),
            PQ("Distinguish between a tendon and a ligament.", "A tendon connects muscle to bone and is non-elastic; a ligament connects bone to bone and is slightly elastic."),
            SUM("A joint is where bones meet: fixed, slightly movable or synovial.",
                "A synovial joint has articular cartilage, synovial fluid, a synovial membrane, a capsule and ligaments.",
                "Ball-and-socket joints (shoulder, hip) move in all directions; hinge joints (elbow, knee) move in one plane.",
                "Pivot joints allow rotation, for example the atlas and axis.",
                "A ligament joins bone to bone; a tendon joins muscle to bone."),
        ],
    ),
    lesson(
        module=M2, topic="Muscles and movement",
        title="Muscles and movement: antagonistic pairs",
        slug="hbi1-muscles-movement", minutes=20,
        summary="Skeletal muscles are attached to bones by tendons and can only pull; movement at a joint is produced by an antagonistic pair, such as the biceps and triceps at the elbow, one contracting while the other relaxes.",
        objectives=["Describe how skeletal muscle is attached to bone",
                    "Explain why muscles work in antagonistic pairs",
                    "Describe the movement of the forearm using biceps and triceps",
                    "Name other antagonistic pairs and the types of muscle in the body"],
        key_concepts=["Skeletal muscle", "Tendon", "Antagonistic muscles", "Flexor", "Extensor", "Contraction"],
        blocks=[
            H("Introduction"),
            T("A porter in the market lifts a sack of maize to his shoulder and lowers it again. His bones cannot move by themselves. They are pulled by muscles. Every movement of the skeleton, from a blink to a long jump, needs muscles, joints and nerves working together."),
            H("Muscles and tendons"),
            T("Skeletal muscles are attached to bones by **tendons**, which are tough and do not stretch. When a muscle receives a nerve impulse, it **contracts** (becomes shorter and thicker) and pulls on the bone it is attached to, which acts like a lever, with the joint as the pivot. When it stops contracting, it **relaxes**."),
            KEY("The key rule", "A muscle can only pull. It cannot push.", cards=[
                ["Contract", "The muscle shortens and pulls the bone."],
                ["Relax", "The muscle becomes long again, but it cannot push the bone back."],
                ["So", "Another muscle on the other side of the bone must contract to pull it back."],
            ]),
            D("**Antagonistic muscles** are a pair of muscles that work in opposite ways: when one contracts the other relaxes. They are arranged on opposite sides of a joint.", title="Definition"),
            H("The biceps and triceps"),
            IMG("f5hbi1-arm-muscles.svg", alt="Arm with biceps in front of the humerus and triceps behind, forearm raised", caption="Figure 1. Antagonistic muscles of the upper arm (schematic)."),
            T("The **biceps** is at the front of the upper arm. It is attached by tendons to the scapula and to the radius. The **triceps** is at the back of the upper arm, attached to the scapula and humerus and to the ulna."),
            CODE("""Movement                Biceps       Triceps      Result at the elbow
Lifting the forearm     Contracts    Relaxes      Joint bends (flexion)
Lowering the forearm    Relaxes      Contracts    Joint straightens (extension)""", "text", title="Elbow movement"),
            T("A muscle that bends a joint is a **flexor** (biceps). A muscle that straightens a joint is an **extensor** (triceps). When the arm is held steady, both muscles contract slightly to keep it in position."),
            T("Other pairs are the quadriceps (front of thigh, extends the knee) and the hamstrings (back of thigh, flexes the knee); the muscles of the calf and shin which move the foot."),
            H("Energy for muscles"),
            T("Muscle cells contain many mitochondria, which release energy from glucose by respiration. During hard exercise, the muscles may not get enough oxygen. They then release energy without oxygen and produce **lactic acid**, which causes tiredness and pain (muscle fatigue). Rest allows oxygen to remove the lactic acid. Warm-up exercises before sport prepare muscles and reduce injury."),
            H("Types of muscle"),
            CODE("""Type                Where                    Control        Features
Skeletal            Attached to bones        Voluntary      Striped, fast, tires
Smooth              Gut, blood vessels,      Involuntary    Slow, does not tire quickly
                    bladder
Cardiac             Heart wall               Involuntary    Never tires, branched cells""", "text", title="Three kinds of muscle"),
            EX("Worked example 1: explain a movement", intro="Explain how the arm is straightened after lifting a load.", steps=[
                S("Name the muscles", text="The triceps is the extensor and the biceps the flexor."),
                S("Describe the action", text="The triceps contracts and pulls on the ulna."),
                S("Describe the other muscle", text="The biceps relaxes."),
                S("Result", text="The elbow joint straightens."),
            ]),
            EX("Worked example 2: why a single muscle is not enough", intro="Why does a joint need two muscles and not one?", steps=[
                S("Recall the rule", text="A muscle can only pull when it contracts."),
                S("Apply", text="One muscle can bend the joint, but when it relaxes nothing straightens the limb."),
                S("Conclude", text="A second muscle on the opposite side pulls the bone back, so the movement can be reversed."),
            ]),
            MISTAKE("Saying the triceps pushes the arm straight", "Muscles never push. The triceps contracts and pulls on the ulna, and that straightens the arm."),
            MISTAKE("Writing that the biceps and triceps both contract to bend the arm", "To bend the arm, the biceps contracts and the triceps relaxes. Together they are antagonistic: one acts while the other releases."),
            QUIZ("When you lower your forearm, which muscle action takes place?", ["Biceps contracts, triceps relaxes", "Biceps relaxes, triceps contracts", "Both contract", "Both relax"], 1,
                 "Straightening the elbow needs the triceps to contract; the biceps relaxes.",
                 hint="The extensor is active when the joint straightens.",
                 feedback=["That lifts the forearm.", "", "Both contracting would hold the arm stiff.", "Nothing would pull the forearm."]),
            QUIZ("A tendon joins", ["bone to bone", "muscle to bone", "muscle to muscle", "cartilage to bone"], 1,
                 "Tendons attach muscle to bone.",
                 hint="Ligaments are the other connectors.",
                 feedback=["That is a ligament.", "", "Tendons attach muscle to bone.", "Not a tendon's function."]),
            TIP("Antagonistic muscles are a favourite in Paper 1 and in structured questions with a labelled diagram of the arm. State which muscle contracts, which relaxes, and what happens to the bone. Use the words 'contracts' and 'relaxes', never 'pushes'."),
            PQ("What is meant by antagonistic muscles? Give an example.", "Muscles that work in opposite ways, so that when one contracts the other relaxes. Example: biceps and triceps."),
            PQ("Describe how the arm is raised (bent) at the elbow.", "The biceps contracts and shortens, pulling on the radius through its tendon. The triceps relaxes. The elbow joint bends and the forearm moves up."),
            PQ("Why do muscles work in pairs?", "A muscle can only pull. A second muscle on the opposite side is needed to pull the bone back."),
            PQ("What causes muscle fatigue?", "Lactic acid builds up when muscles work hard without enough oxygen, and the muscle also runs short of energy."),
            SUM("Muscles are joined to bones by tendons and move them by contracting.",
                "A muscle can pull but cannot push, so joints are worked by antagonistic pairs.",
                "Raising the forearm: biceps contracts, triceps relaxes. Lowering: triceps contracts, biceps relaxes.",
                "A flexor bends a joint; an extensor straightens it.",
                "Muscle may be skeletal, smooth or cardiac."),
        ],
    ),
    lesson(
        module=M2, topic="Posture, fractures, sprains and first aid",
        title="Posture, fractures, sprains and first aid",
        slug="hbi1-posture-fractures-first-aid", minutes=22,
        summary="Good posture protects the backbone; fractures (broken bones), sprains (torn ligaments) and dislocations are common injuries, and simple first aid (support, rest, no unnecessary movement, then seek a health worker) prevents more harm.",
        objectives=["Describe good posture and the problems caused by poor posture",
                    "Name the main types of fracture and describe how a bone heals",
                    "Distinguish a fracture, a sprain, a strain and a dislocation",
                    "State general first-aid steps for bone and joint injuries"],
        key_concepts=["Posture", "Fracture", "Sprain", "Dislocation", "First aid", "Splint"],
        blocks=[
            H("Introduction"),
            T("Many students in Cameroon carry heavy bags to school and sit on benches for hours. Many women carry water or goods on the head and back, and many people ride motorbike taxis. Each of these can harm the bones and joints if done badly. This lesson looks at how to keep the skeleton healthy, and what to do when injury happens."),
            D("**Posture** is the way the body is held when standing, sitting or moving.", title="Definition"),
            H("Good and poor posture"),
            T("Good posture keeps the natural S-curve of the backbone, so that the weight is shared evenly and the muscles and ligaments are not overstrained."),
            KEY("Habits for good posture", "Simple actions protect the back.", cards=[
                ["Standing", "Head up, shoulders back, back straight, weight on both feet."],
                ["Sitting", "Back straight and supported, feet flat on the floor, desk at the right height."],
                ["Lifting", "Bend the knees, keep the back straight, hold the load close to the body, and let the leg muscles do the work."],
                ["Carrying", "Spread weight evenly; use both straps of a school bag; do not carry too much."],
            ]),
            T("Poor posture strains muscles and ligaments, causing backache and tiredness. Over a long time the backbone can become abnormally curved. Three examples are **scoliosis** (a sideways curve), **kyphosis** (an excess outward curve of the upper back, 'hunchback') and **lordosis** (an excess inward curve of the lower back). Poor diet (little calcium and vitamin D), being overweight and injuries can also lead to deformities. A person with a persistent back problem should see a health worker."),
            H("Fractures"),
            D("A **fracture** is a break or crack in a bone, caused by a fall, a blow or a road accident.", title="Definition"),
            CODE("""Type                Description
Simple (closed)     Bone broken, skin not broken
Compound (open)     Bone broken and the skin torn; bone may show; risk of infection
Greenstick          Bone bent and cracked on one side only; common in children
Comminuted          Bone broken into several pieces
Hairline (stress)   A fine crack; may be caused by repeated stress""", "text", title="Types of fracture"),
            T("A broken bone heals by itself if the broken ends are held still in the right position. A blood clot forms around the break; new cells and cartilage make a soft **callus** that joins the ends; this is replaced by new bone; and finally the bone is reshaped. A plaster cast or a splint holds the bone still. Healing takes weeks, and children heal faster than old people. Enough calcium, vitamin D and protein help."),
            H("Sprains, strains and dislocations"),
            CODE("""Injury         What is damaged                     Typical signs
Sprain         Ligament stretched or torn at joint  Pain, swelling, bruising; hard to move the joint
Strain         Muscle or tendon pulled or torn      Pain and weakness in the muscle
Dislocation    Bone pulled out of its joint         Joint looks deformed, very painful, cannot move
Fracture       Bone cracked or broken               Pain, swelling, deformity, cannot use the part""", "text", title="Joint and bone injuries"),
            H("First aid"),
            D("**First aid** is the immediate help given to an injured person before a health worker or hospital takes over. It aims to preserve life, prevent the injury getting worse and help recovery.", title="Definition"),
            T("These are general guidelines only; first aid does not replace a health worker. If a bone is broken or a joint dislocated, the person should be taken to a health centre or hospital as soon as possible."),
            KEY("General first aid for suspected fracture", "Keep it simple and safe.", cards=[
                ["Keep still", "Do not move the injured person or the injured part more than necessary, especially if the neck or back may be hurt."],
                ["Support", "Support the injured limb in the position found; a splint (a firm piece of wood or folded cloth) padded and tied above and below the break may be used."],
                ["Bleeding", "If there is a wound, cover it with a clean cloth and press gently around it; do not push a bone back in."],
                ["Do not", "Do not massage the injury, do not try to straighten a bone, and do not give food or drink if the person may need an operation."],
                ["Get help", "Seek a health worker or take the person to hospital."],
            ]),
            T("For a **sprain**, the usual advice is **RICE**: Rest, Ice (a cold wet cloth), Compression (a firm bandage, not tight) and Elevation (raise the limb). Seek a health worker if the pain is severe or the swelling does not go down."),
            EX("Worked example 1: classify the injury", intro="After a fall from a bicycle, a boy has a swollen ankle that hurts when moved, with no deformity. A second boy has a forearm that is bent in an odd shape and cannot be used. Name the likely injury in each.", steps=[
                S("First boy", text="Pain and swelling at a joint without deformity suggests a sprain of the ligament."),
                S("Second boy", text="A deformed forearm that cannot be used suggests a fracture."),
                S("Advice", text="Both should be seen by a health worker; the second needs the arm supported and kept still."),
            ]),
            EX("Worked example 2: lifting a load", intro="A student must lift a heavy bag of rice from the floor. Describe the correct way.", steps=[
                S("Stand close", text="Place the feet apart, close to the bag."),
                S("Bend the knees", text="Bend the knees, not the back, and keep the back straight."),
                S("Lift with the legs", text="Hold the load close to the body and straighten the legs."),
            ]),
            MISTAKE("Rubbing or massaging a fracture", "This can move the broken ends and cause more damage. Keep still and support the injury."),
            MISTAKE("Confusing a sprain with a strain", "A sprain is injury to a ligament at a joint. A strain is injury to a muscle or tendon."),
            QUIZ("A tear of a ligament at the ankle is called a", ["fracture", "sprain", "strain", "dislocation"], 1,
                 "A sprain is a stretched or torn ligament at a joint.",
                 hint="Ligaments join bone to bone.",
                 feedback=["A fracture is a broken bone.", "", "A strain is a muscle or tendon injury.", "A dislocation is a bone out of position."]),
            QUIZ("Which action is correct first aid for a suspected broken arm?", ["Massage the arm", "Try to straighten the bone", "Support and keep the arm still, then seek a health worker", "Ask the person to move it to test it"], 2,
                 "Support the arm, avoid movement, and seek a health worker.",
                 hint="The aim is to prevent further damage.",
                 feedback=["Massage can cause more damage.", "Never try to straighten a bone.", "", "Moving it may worsen the injury."]),
            TIP("This topic is part of the skeletal system. Expect questions on types of fracture, sprain versus fracture, and first aid steps. Use simple 'what to do' sentences, and always include 'seek a health worker' at the end of first-aid answers."),
            PQ("Name two types of fracture and describe each.", "Simple: bone broken, skin intact. Compound: bone broken and the skin torn (also greenstick and comminuted)."),
            PQ("State three habits that give a good posture.", "Stand with head up and back straight; sit with the back supported and feet flat; lift by bending the knees; carry loads evenly. Any three."),
            PQ("Describe the first aid you would give to a person with a suspected broken leg.", "Keep the person still and the leg supported in position; use a padded splint if trained; cover any wound with a clean cloth; do not move or straighten the bone; seek a health worker or hospital."),
            PQ("Explain the difference between a sprain and a dislocation.", "A sprain is a torn or stretched ligament; the bones stay in place. A dislocation is when the bone end is pulled out of its joint."),
            SUM("Good posture keeps the natural curves of the backbone and protects muscles and ligaments.",
                "Fractures may be simple, compound, greenstick or comminuted; bones heal through a callus.",
                "A sprain is a ligament injury; a strain is a muscle or tendon injury; a dislocation moves a bone out of its joint.",
                "First aid for a fracture: keep still, support, cover wounds, do not straighten, seek a health worker.",
                "For a sprain use rest, ice, compression and elevation, and see a health worker if severe."),
        ],
    ),
]
